public class GradeScaleCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(GradeScale impl) {
        try {
            return GradeScaleChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectScale()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectScale()));
        check("rejects the > that should have been >=", false, verdict(new StrictBoundaryScale()));
        check("rejects the missing D band", false, verdict(new NoDScale()));
        check("rejects the version that grades impossible scores", false, verdict(new UnvalidatedScale()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectScale implements GradeScale {
    public String letterFor(int score) {
        if (score < 0 || score > 100) return "?";
        if (score >= 90) return "A";
        if (score >= 80) return "B";
        if (score >= 70) return "C";
        if (score >= 60) return "D";
        return "F";
    }
}

class AlsoCorrectScale implements GradeScale {
    public String letterFor(int score) {
        if (score < 0 || score > 100) return "?";
        switch (score / 10) {
            case 10: case 9: return "A";
            case 8: return "B";
            case 7: return "C";
            case 6: return "D";
            default: return "F";
        }
    }
}

