/**
 * TASK: Write the checks that decide whether a GradeScale is correct.
 *
 *   letterFor(score) returns the letter grade for a score out of 100:
 *     90..100 -> "A",  80..89 -> "B",  70..79 -> "C",
 *     60..69  -> "D",  0..59  -> "F"
 *   A score below 0 or above 100 is not a score at all: return "?".
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface GradeScale {
    /* Provided -- do not edit. */
    String letterFor(int score);
}

public class GradeScaleChecker {

    public static boolean isCorrect(GradeScale impl) {
        try {
            if (!"A".equals(impl.letterFor(100))) return false;
            if (!"A".equals(impl.letterFor(90))) return false;
            if (!"B".equals(impl.letterFor(89))) return false;
            if (!"B".equals(impl.letterFor(80))) return false;
            if (!"C".equals(impl.letterFor(70))) return false;
            if (!"D".equals(impl.letterFor(69))) return false;
            if (!"D".equals(impl.letterFor(60))) return false;
            if (!"F".equals(impl.letterFor(59))) return false;
            if (!"F".equals(impl.letterFor(0))) return false;
            if (!"?".equals(impl.letterFor(-1))) return false;
            if (!"?".equals(impl.letterFor(101))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
